<?php
require_once __DIR__.'/app/lib/Db.php';
require_once __DIR__.'/app/lib/PartnerDiscovery.php';
$pdo=Db::pdo();
$slug=trim((string)($_GET['software']??''));$country=strtoupper(trim((string)($_GET['country']??'')));$city=trim((string)($_GET['city']??''));
$services=$_GET['service']??[];if(!is_array($services))$services=[$services];
$product=null;$partners=[];$countries=[];
if($slug!==''){$st=$pdo->prepare("SELECT p.id,p.name,p.slug,p.short_description,v.name vendor_name FROM products p LEFT JOIN vendors v ON v.id=p.vendor_id WHERE p.slug=? AND p.status='active' LIMIT 1");$st->execute([$slug]);$product=$st->fetch(PDO::FETCH_ASSOC);if($product)$partners=PartnerDiscovery::find($pdo,(int)$product['id'],$country,$services,$city);}
try{$countries=$pdo->query("SELECT code,name FROM countries ORDER BY name")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){}
$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
