adding:24px;text-align:center;color:#64748b}@media(max-width:760px){.form{grid-template-columns:1fr}.hero{padding:18px}}</style></head><body><main><a class="brand" href="/">TechSelectAI</a><section class="hero"><div class="badge">Verified provider discovery</div><h1><?= $product?'Find vendors and implementation partners for '.$esc($product['name']):'Find local software vendors and implementation partners' ?></h1><p class="muted">Provider results are based on verified company↔software relationships and territory evidence. Provider ordering is separate from TechSelectAI software evaluation and recommendation ranking.</p><form method="get" action="/partners"><div class="form"><div><label>Software</label><input name="software" value="<?=$esc($slug)?>" placeholder="software-slug" required></div><div><label>Country</label><select name="country"><option value="">Any verified territory</option><?php foreach($countries as $c): ?><option value="<?=$esc($c['code'])?>" <?=$country===$c['code']?'selected':''?>><?=$esc($c['name'])?></option><?php endforeach; ?></select></div><div><label>City (optional)</label><input name="city" value="<?=$esc($city)?>" placeholder="e.g. Riyadh"></div></div><div class="services"><?php foreach(PartnerDiscovery::SERVICE_TYPES as $key=>$label): ?><label><input type="checkbox" name="service[]" value="<?=$esc($key)?>" <?=in_array($key,$services,true)?'checked':''?>> <?=$esc($label)?></label><?php endforeach; ?></div><button type="submit">Find verified providers</button></form></section><?php if($slug!==''&&!$product): ?><div class="notice">Software not found or not publicly active.</div><?php elseif($product): ?><section class="panel"><h2><?=count($partners)?> verified provider<?=count($partners)===1?'':'s'?></h2><p class="muted">Ordering: exact city/country matches → broader regional coverage → global/remote coverage. Within the same territory tier, verification completeness and evidence presence are used only to order providers.</p><?php if($partners): ?><div class="grid"><?php foreach($partners as $p): ?><article class="card"><div class="badge"><?=$esc($p['match_label'])?></div><h3><?=$esc($p['vendor_name'])?></h3><div class="meta"><?=$esc($p['relationship_label'])?> · <?=$esc($p['freshness']['label']??'Verified')?></div><div class="territories"><?php foreach($p['territories'] as $t): ?><span><?=$esc($t['territory_name'])?></span><?php endforeach; ?></div><div class="verify"><strong>Verification:</strong> relationship verified<?=!empty($p['verified_at'])?' · reviewed '.$esc(substr($p['verified_at'],0,10)):''?><?=!empty($p['valid_until'])?' · valid until '.$esc($p['valid_until']):''?></div><p class="links"><a href="/vendors/<?=$esc($p['vendor_slug'])?>">Company profile</a><?php if(!empty($p['website_url'])): ?><a href="<?=$esc($p['website_url'])?>" rel="nofollow noopener" target="_blank">Company website</a><?php endif; ?><?php if(!empty($p['evidence_source_url'])): ?><a href="<?=$esc($p['evidence_source_url'])?>" rel="nofollow noopener" target="_blank">Relationship evidence</a><?php endif; ?></p></article><?php endforeach; ?></div><?php else: ?><div class="empty">No verified providers currently match this location and service filter. Try removing a service filter or selecting another territory.</div><?php endif; ?><div class="notice"><strong>Neutrality:</strong> provider presence or ordering does not change the independent software score, contextual fit, shortlist ranking, or recommendation. Any future sponsored placement must be labeled separately.</div></section><?php endif; ?></main></body></html>